static class Rectangle {
    int width;
    int height;

    Rectangle(int width, int height) {
        width = width;
        height = height;
    }

    int area() {
        return width * height;
    }

    int perimeter() {
        return 2 * (width + height);
    }
}

tests:
Rectangle r = new Rectangle(3, 4);
checkEq(r.area(), 12);
checkEq(r.perimeter(), 14);

